    def totalFruit(self, fruits: list[int]) -> int:
        counts: dict[int, int] = {}
        start = best = 0
        for end, fruit in enumerate(fruits):
            counts[fruit] = counts.get(fruit, 0) + 1
            while len(counts) > 2:
                leaving = fruits[start]
