class Solution {
    public int calPoints(String[] operations) {
        Deque<Integer> scores = new ArrayDeque<>();
        for (String op : operations) {
            if (op.equals("C")) scores.removeLast();
            else if (op.equals("D")) scores.addLast(2 * scores.peekLast());
            else if (op.equals("+")) { int last = scores.removeLast(); int sum = last + scores.peekLast(); scores.addLast(last); scores.addLast(sum); }
            else scores.addLast(Integer.parseInt(op));
        }
        return scores.stream().mapToInt(Integer::intValue).sum();
    }
}

