class Solution {
    public String minWindow(String s, String t) {
        int[] need = new int[128]; for (char c : t.toCharArray()) need[c]++;
        int missing=t.length(), left=0, start=0, best=Integer.MAX_VALUE;
        for (int right=0; right<s.length(); right++) { char c=s.charAt(right); if (need[c]-- > 0) missing--;
            while (missing==0) { if (right-left+1<best) { start=left; best=right-left+1; } char x=s.charAt(left++); if (++need[x]>0) missing++; }
        }
        return best==Integer.MAX_VALUE ? "" : s.substring(start,start+best);
    }
}

