        for(int right=0; right<(int)s.size(); ++right) { unsigned char c=s[right]; if(need[c]-- > 0) --missing;
            while(missing==0) { if(right-left+1<best) {start=left; best=right-left+1;} unsigned char x=s[left++]; if(++need[x]>0) ++missing; }
        }
        return best>(int)s.size()?"":s.substr(start,best);
    }
};

