def min_energy(n: int, edges: list[list[int]], k: int) -> int:
    graph=[[] for _ in range(n)]
    for u,v,w,deep in edges: graph[u].append((v,w,deep)); graph[v].append((u,w,deep))
    dist=[[inf]*(k+1) for _ in range(n)]; dist[0][0]=0; heap=[(0,0,0)]
    while heap:
        d,u,used=heappop(heap)
        if d!=dist[u][used]: continue
        for v,w,deep in graph[u]:
            for nd,nu in ((d+w,used),(d,used+1) if deep and used<k else (inf,used)):
                if nd<dist[v][nu]: dist[v][nu]=nd; heappush(heap,(nd,v,nu))
    ans=min(dist[-1]); return -1 if ans==inf else ans

