class Solution:
    def rightSideView(self, root: TreeNode | None) -> list[int]:
        if not root: return []
        result=[]; q=deque([root])
        while q:
            for i in range(len(q)):
                node=q.popleft()
                if node.left: q.append(node.left)
                if node.right: q.append(node.right)
                if i==0: visible=node.val
            result.append(visible)
        return result

